// Thai script course (文字): lessons and data in script-data.js (SCRIPT_DATA). Progress lives in its own key so
// grammar (thai-steps-v1) and word (thai-steps-words-v1) records are untouched.
const SCRIPT_KEY='thai-steps-script-v1';
let scriptState={done:[],games:{}},scriptCurrent=null,scriptQuiz=null,scriptShowRo=true;
// Best scores of the 文字ゲーム (script-game.js). Anything that is not a finite number in range is dropped, so a
// hand-edited backup (or 1e999 → Infinity) cannot leave an unbeatable record.
function sanitizeScriptGames(g){const out={};if(!g||typeof g!=='object'||Array.isArray(g))return out;
 const best=v=>typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<=100000?Math.round(v):null,time=v=>typeof v==='number'&&Number.isFinite(v)&&v>=3&&v<=3600?Math.round(v*10)/10:null;
 for(const k of ['speed','listen','tone']){const b=g[k]&&typeof g[k]==='object'?best(g[k].best):null;if(b!==null)out[k]={best:b}}
 const t=g.match&&typeof g.match==='object'?time(g.match.bestTime):null;if(t!==null)out.match={bestTime:t};return out}
try{const s=JSON.parse(localStorage.getItem(SCRIPT_KEY)||'{}');if(Array.isArray(s.done))scriptState.done=s.done.filter(x=>typeof x==='string');scriptState.games=sanitizeScriptGames(s.games)}catch(e){}
function saveScript(){try{localStorage.setItem(SCRIPT_KEY,JSON.stringify(scriptState))}catch(e){}}
const SCRIPT_TONES={mid:'平声',low:'低声',falling:'下声',high:'高声',rising:'上声'};
const SCRIPT_CLASS={mid:'中子音',high:'高子音',low:'低子音'};
function scriptData(){return typeof SCRIPT_DATA==='undefined'?{consonants:[],vowels:[],toneMarks:[],digits:[],lessons:[]}:SCRIPT_DATA}
function scriptLessons(){return scriptData().lessons}
function scriptStages(){const out=[];for(const l of scriptLessons()){let s=out.find(x=>x.stage===l.stage);if(!s)out.push(s={stage:l.stage,title:l.stageTitle,lessons:[]});s.lessons.push(l)}return out}
function scriptStageComplete(s){return s.lessons.every(l=>scriptState.done.includes(l.id))}
function scriptNext(){return scriptLessons().find(l=>!scriptState.done.includes(l.id))||scriptLessons()[0]}
function consonantInfo(ch){return scriptData().consonants.find(c=>c.ch===ch)}
function vowelInfo(form){return scriptData().vowels.find(v=>v.form===form)}
function markInfo(m){return [...scriptData().toneMarks,...(scriptData().signs||[])].find(x=>x.mark===m)}
function digitInfo(ch){return (scriptData().digits||[]).find(x=>x.ch===ch)}
// Everything taught up to and including lesson index i.
function scriptLearned(i){const ls=scriptLessons().slice(0,i+1);return {consonants:ls.flatMap(l=>l.newConsonants||[]),vowels:ls.flatMap(l=>l.newVowels||[]),readings:ls.flatMap(l=>l.readings||[])}}
function openScript(){view='script';scriptCurrent=null;scriptQuiz=null;render();window.scrollTo(0,0)}
function openScriptLesson(id){scriptCurrent=id;scriptQuiz=null;view='scriptLesson';render();window.scrollTo(0,0)}
function speakScript(text,slow=false){speakThaiText(text,slow)}
function scriptAudio(text,label='音'){return `<button type="button" class="s-audio is-icon" data-th="${esc(text)}" aria-label="${esc(text)}を再生" title="${esc(label)}" onclick="speakScript(this.dataset.th)">${icon('audio')}</button>`}
function scriptHomeCard(){const ls=scriptLessons();if(!ls.length)return '';const n=ls.filter(l=>scriptState.done.includes(l.id)).length,next=scriptNext();return `<article class="x-card s-home-card"><div class="x-card-head"><h2>${icon('script')} 文字</h2><span>${n} / ${ls.length} 課</span></div><p class="x-next">${n===ls.length?'全課を履修済み':`次の課 · ${esc(next.stageTitle)}`}</p><h3 class="x-lesson">${n===ls.length?'タイ文字を読めるようになりました。':esc(next.title)}</h3><div class="track"><div style="width:${n/ls.length*100}%"></div></div><div class="x-card-actions"><button class="btn" onclick="${n===ls.length?'openScript()':`openScriptLesson('${next.id}')`}">${n?'続きから学ぶ':'文字をはじめる'} ${icon('arrow')}</button><button class="btn light" onclick="openScript()">一覧</button></div></article>`}
function scriptView(){const ls=scriptLessons();if(!ls.length)return '<div class="empty">文字の教材を読み込めませんでした。</div>';const done=ls.filter(l=>scriptState.done.includes(l.id)).length;
 return `<div class="x-head"><h1>文字</h1><span class="x-inventory">${scriptStages().length}段階 · ${ls.length}課 · 履修済み ${done}</span></div><p class="s-lead">一度に覚える字は数個ずつ。字の形と音を見て聞き、読み練習をしてから確認テストへ。全問正解でその課は履修済みになります。</p>${typeof scriptGameCard==='function'?scriptGameCard():''}${typeof soundCards==='function'?soundCards():''}${scriptStages().map(s=>`<section class="x-course-chapter${scriptStageComplete(s)?' is-complete':''}"><div class="x-section-head"><h2><span class="x-chapter-icon s-stage-num" aria-hidden="true">${s.stage}</span>${esc(s.title)}</h2><span>${scriptStageComplete(s)?'✓ 履修済み':`${s.lessons.filter(l=>scriptState.done.includes(l.id)).length} / ${s.lessons.length}`}</span></div><div class="x-lessons">${s.lessons.map(l=>{const d=scriptState.done.includes(l.id),glyphs=[...(l.newConsonants||[]),...(l.newVowels||[]).map(v=>v.replace(/\([a-z]+\)/g,'').replace(/[–-]/g,'◌')),...(l.newMarks||[]),...(l.newDigits||[])].filter(Boolean).slice(0,8).join(' ');return `<button class="x-lesson-row" onclick="openScriptLesson('${l.id}')"><span class="x-lesson-num${d?' done':''}" aria-label="${d?'履修済み':'未学習'}">${d?icon('check'):esc(l.id.replace(/^s0?/,''))}</span><span class="x-lesson-body"><b>${thaiRuns(l.title)}</b><small class="s-row-glyphs" lang="th">${esc(glyphs)}</small></span><span class="x-lesson-end">${icon('arrow')}</span></button>`}).join('')}</div></section>`).join('')}`}
function consonantCard(ch){const c=consonantInfo(ch);if(!c)return '';return `<div class="s-card s-${c.cls}"><div class="s-glyph" lang="th">${esc(c.ch)}</div><div class="s-card-body"><span class="s-class">${SCRIPT_CLASS[c.cls]||''}</span><b class="s-name-ro">${esc(c.nameRo)}</b><span class="s-name" lang="th">${esc(c.name)}</span><span class="s-name-ja">${esc(c.nameJa||'')}</span><span class="s-sounds">頭 <b>${esc(c.initial)}</b>${c.final?` · 末 <b>${esc(c.final)}</b>`:''}</span>${c.note?`<span class="s-note">${esc(c.note)}</span>`:''}${scriptAudio(c.name,'名前')}</div></div>`}
function vowelCard(form){const v=vowelInfo(form);if(!v)return '';return `<div class="s-card s-vowel"><div class="s-glyph" lang="th">${esc(v.form.replace(/[–-]/g,'◌'))}</div><div class="s-card-body"><span class="s-class">${v.length==='short'?'短母音':v.length==='long'?'長母音':'母音'}</span><b class="s-name-ro">${esc(v.ro)}</b>${v.note?`<span class="s-note">${esc(v.note)}</span>`:''}</div></div>`}
function markCard(m){const x=markInfo(m);if(!x)return '';return `<div class="s-card s-mark"><div class="s-glyph" lang="th">◌${esc(x.mark)}</div><div class="s-card-body"><span class="s-class">${scriptData().toneMarks.some(t=>t.mark===x.mark)?'声調記号':'記号'}</span><b class="s-name-ro">${esc(x.nameRo)}</b><span class="s-name" lang="th">${esc(x.name)}</span>${x.note?`<span class="s-note">${esc(x.note)}</span>`:''}</div></div>`}
function digitCard(ch){const x=digitInfo(ch);if(!x)return '';return `<div class="s-card s-digit"><div class="s-glyph" lang="th">${esc(x.ch)}</div><div class="s-card-body"><span class="s-class">数字 ${x.value}</span><b class="s-name-ro">${esc(x.ro)}</b></div></div>`}
// Thai runs (and the dotted circle that carries a lone mark) in the Thai font, so ◌่ draws as one glyph.
const thaiRuns=s=>esc(s).replace(/[\u0e00-\u0e7f◌]+/g,m=>`<span lang="th" class="s-th-run">${m}</span>`);
function scriptLessonView(){const ls=scriptLessons(),i=ls.findIndex(l=>l.id===scriptCurrent),l=ls[i];if(!l)return scriptView();const done=scriptState.done.includes(l.id);
 return `<button class="textbtn back" onclick="openScript()">← 文字の一覧に戻る</button><div class="eyebrow">STAGE ${l.stage} · ${esc(l.stageTitle)}</div><h1 class="lesson-title">${thaiRuns(l.title)}</h1><section class="panel"><div class="panel-kicker">01 / 字を知る</div><p class="intro">${thaiRuns(l.intro)}</p>${(l.newConsonants||[]).length+(l.newVowels||[]).length+(l.newMarks||[]).length+(l.newDigits||[]).length?`<div class="s-cards">${(l.newConsonants||[]).map(consonantCard).join('')}${(l.newVowels||[]).map(vowelCard).join('')}${(l.newMarks||[]).map(markCard).join('')}${(l.newDigits||[]).map(digitCard).join('')}</div>`:''}${(l.points||[]).length?`<ul class="points">${l.points.map(p=>`<li>${thaiRuns(p)}</li>`).join('')}</ul>`:''}</section>
 ${(l.readings||[]).length?`<section class="panel"><div class="s-panel-head"><div><div class="panel-kicker">02 / 読んでみる</div><h2>読み練習</h2></div><button class="textbtn" onclick="scriptShowRo=!scriptShowRo;render()">${scriptShowRo?'読みを隠す':'読みを表示'}</button></div><p class="subtext">タイ文字を自分で読んでから、音と読みで確かめましょう。</p><div class="s-readings">${l.readings.map(r=>`<div class="s-reading"><span class="s-reading-th" lang="th">${esc(r.th)}</span><span class="s-reading-ro${scriptShowRo?'':' is-hidden'}" lang="th-Latn">${esc(r.ro)}</span>${r.ja?`<span class="s-reading-ja${scriptShowRo?'':' is-hidden'}">${esc(r.ja)}</span>`:''}${scriptAudio(r.th)}</div>`).join('')}</div></section>`:''}
 <section class="panel"><div class="panel-kicker">03 / 確かめる</div><h2>確認テスト</h2><p class="subtext">${scriptQuestions(i).length}問。全問正解でこの課は履修済みになります。</p><div class="settings-row"><button class="btn" onclick="startScriptQuiz('${l.id}')">確認テストを解く（${scriptQuestions(i).length}問） →</button>${done?'<span class="x-done-badge">✓ 履修済み</span>':''}</div></section>
 <div class="bottom-actions"><button class="btn light" ${i===0?'disabled':''} onclick="openScriptLesson('${ls[Math.max(0,i-1)].id}')">← 前の課</button><button class="btn light" ${i===ls.length-1?'disabled':''} onclick="openScriptLesson('${ls[Math.min(ls.length-1,i+1)].id}')">次の課 →</button></div>`}
// Up to 10 questions built from the lesson: new letters (sound, class), new vowels, readings and tones.
function pick(arr,n,avoid=[]){const out=[];for(const x of shuffle([...arr]))if(!avoid.includes(x)&&!out.includes(x)){out.push(x);if(out.length===n)break}return out}
// Distractors with the same number of syllables, so the length of an option does not give the answer away.
function choices(correct,pool){const n=String(correct).split(' ').length,same=pool.filter(x=>x!==correct&&String(x).split(' ').length===n),wrong=pick(same.length>=2?same:pool.filter(x=>x!==correct),2);return wrong.length<2?null:shuffle([correct,...wrong])}
function scriptQuestions(i){const l=scriptLessons()[i];if(!l)return [];const L=scriptLearned(i),all=scriptData(),qs=[];
 const initials=[...new Set(all.consonants.map(c=>c.initial))],learnedCons=L.consonants.map(consonantInfo).filter(Boolean);
 for(const ch of l.newConsonants||[]){const c=consonantInfo(ch);if(!c)continue;
  const o=choices(c.initial,[...new Set([...learnedCons.map(x=>x.initial),...initials])]);if(o)qs.push({prompt:'この字の音（頭子音）は？',glyph:c.ch,options:o,answer:c.initial,why:`${c.ch}（${c.nameRo}）は頭子音 ${c.initial} の音です。`});
  if(l.stage>=3){qs.push({prompt:'この字のクラスは？',glyph:c.ch,options:['中子音','高子音','低子音'],answer:SCRIPT_CLASS[c.cls],why:`${c.ch} は${SCRIPT_CLASS[c.cls]}です。クラスで声調の決まり方が変わります。`})}}
 for(const f of l.newVowels||[]){const v=vowelInfo(f);if(!v)continue;const o=choices(v.ro,[...new Set([...L.vowels.map(vowelInfo).filter(Boolean).map(x=>x.ro),...all.vowels.map(x=>x.ro)])]);if(o)qs.push({prompt:'この母音の読みは？',glyph:v.form.replace(/[–-]/g,'◌'),options:o,answer:v.ro,why:`${v.form.replace(/[–-]/g,'◌')} は ${v.ro} と読みます。`})}
 for(const ch of l.newDigits||[]){const x=digitInfo(ch);if(!x)continue;const o=choices(String(x.value),(scriptData().digits||[]).map(d=>String(d.value)));if(o)qs.push({prompt:'この数字は？',glyph:x.ch,options:o,answer:String(x.value),why:`${x.ch} は ${x.value}（${x.ro}）です。`})}
 const rpool=[...new Set(L.readings.map(r=>r.ro))];for(const r of l.readings||[]){const o=choices(r.ro,rpool);if(o)qs.push({prompt:'読み方は？',glyph:r.th,options:o,answer:r.ro,why:`${r.th} は ${r.ro}${r.ja?`（${r.ja}）`:''}。`,speak:r.th})}
 for(const t of l.toneQuestions||[]){const o=shuffle([SCRIPT_TONES[t.tone],...pick(Object.values(SCRIPT_TONES).filter(x=>x!==SCRIPT_TONES[t.tone]),2)]);qs.push({prompt:'声調は？',glyph:t.th,options:o,answer:SCRIPT_TONES[t.tone],why:t.why||'',speak:t.th})}
 // Letters and tones first, then readings, capped at 10 so every lesson's test has the same size.
 const head=qs.filter(q=>q.prompt!=='読み方は？'),reads=qs.filter(q=>q.prompt==='読み方は？');return [...pick(head,Math.min(head.length,6)),...pick(reads,10)].slice(0,10)}
function startScriptQuiz(id){const i=scriptLessons().findIndex(l=>l.id===id);scriptQuiz={id,qs:shuffle(scriptQuestions(i)),i:0,results:[],choice:null};view='scriptQuiz';render();window.scrollTo(0,0)}
function scriptAnswer(n){const q=scriptQuiz.qs[scriptQuiz.i];if(scriptQuiz.choice!==null)return;scriptQuiz.choice=n;const ok=q.options[n]===q.answer;scriptQuiz.results.push(ok);
 if(scriptQuiz.results.length===scriptQuiz.qs.length&&scriptQuiz.results.every(Boolean)&&!scriptState.done.includes(scriptQuiz.id)){scriptState.done.push(scriptQuiz.id);saveScript()}render()}
function scriptNextQuestion(){scriptQuiz.i++;scriptQuiz.choice=null;render();window.scrollTo(0,0)}
function scriptQuizView(){const s=scriptQuiz,ls=scriptLessons(),li=ls.findIndex(l=>l.id===s.id),l=ls[li];
 if(s.i>=s.qs.length){const yes=s.results.filter(Boolean).length,all=yes===s.qs.length;return `<div class="quiz-wrap"><div class="empty quiz-result${all?' is-complete':''}"><div class="eyebrow">STAGE ${l.stage} · ${esc(l.title)}</div><h1>${yes} / ${s.qs.length} 問 正解</h1><p class="subtext">${all?'全問正解！この課を履修済みにしました。':`全${s.qs.length}問正解で履修済みになります。字と読みを見直して、もう一度。`}</p><div class="settings-row" style="justify-content:center"><button class="btn" onclick="startScriptQuiz('${l.id}')">もう一度解く</button>${all&&li<ls.length-1?`<button class="btn light" onclick="openScriptLesson('${ls[li+1].id}')">次の課へ →</button>`:''}<button class="btn light" onclick="openScriptLesson('${l.id}')">戻る</button></div></div></div>`}
 const q=s.qs[s.i],answered=s.choice!==null,ok=answered&&q.options[s.choice]===q.answer;
 return `<div class="quiz-wrap"><button class="textbtn back" onclick="openScriptLesson('${l.id}')">← 問題を終了する</button><div class="quiz-top"><span class="subtext">${s.i+1} / ${s.qs.length} 問<small> · 全問正解で履修済み</small></span><div class="track"><div style="width:${s.i/s.qs.length*100}%"></div></div></div><section class="panel"><div class="eyebrow">STAGE ${l.stage} · ${esc(l.title)}</div><h2 class="quiz-q">${esc(q.prompt)}</h2><div class="s-quiz-glyph" lang="th">${esc(q.glyph)}</div>${q.speak&&answered?`<div class="s-quiz-audio">${scriptAudio(q.speak,'音を聞く')}</div>`:''}${q.options.map((o,n)=>`<button class="option quiz-option ${answered&&o===q.answer?'correct':''} ${answered&&n===s.choice&&!ok?'wrong':''}" ${answered?'disabled':''} onclick="scriptAnswer(${n})">${answered&&o===q.answer?'<span class="quiz-mark">✓</span>':''}<span class="${/[a-zɛɔəʉŋ]/.test(o)&&!/[฀-๿]/.test(o)?'quiz-ro':'quiz-ja'}">${esc(o)}</span></button>`).join('')}${answered?`<div class="feedback ${ok?'':'bad'}" role="status"><strong>${ok?'正解！':'もう一度、形を確かめよう。'}</strong><br>${esc(q.why)}</div><div class="bottom-actions"><button class="textbtn" onclick="openScriptLesson('${l.id}')">課に戻る</button><button class="btn" onclick="scriptNextQuestion()">${s.i===s.qs.length-1?'結果を見る':'次の問題'} →</button></div>`:''}</section></div>`}
